-- 20260613000300_oauth_states_table.sql
-- Cloud Run multi-instance OAuth state store.
--
-- Calendar OAuth previously kept state in a module-level Python dict in
-- backend/routers/calendar_booking.py. On Cloud Run with --max-instances > 1
-- the state generated by oauth_authorize on instance A is invisible to
-- instance B when Google redirects the user back, causing every callback to
-- fail with reason=invalid_state if the load balancer routes the redirect to
-- a different revision. This table replaces the in-memory dict with a
-- shared, atomic store. The in-memory dict is preserved as a local-dev
-- fallback for environments where Supabase is unreachable.
--
-- Only the FastAPI service role accesses this table; no per-user RLS is
-- required. The single service-role ALL policy is the entire access surface.

CREATE TABLE IF NOT EXISTS public.oauth_states (
    state       text PRIMARY KEY,
    tenant_id   uuid NOT NULL,
    provider    text NOT NULL CHECK (provider IN ('google', 'microsoft')),
    payload     jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_oauth_states_expires
    ON public.oauth_states(expires_at);

ALTER TABLE public.oauth_states ENABLE ROW LEVEL SECURITY;

-- Service role is the only consumer; no user-level policy needed.
DROP POLICY IF EXISTS oauth_states_service_role ON public.oauth_states;
CREATE POLICY oauth_states_service_role ON public.oauth_states FOR ALL
    USING (auth.role() = 'service_role');
